```python
def play_again():
"""Ask the player if they want to play another round."""
while True:
answer = input("Play again? (y/n): ").strip().lower()
if answer == 'y':
return True
elif answer == 'n':
return False
else:
print("Please enter 'y' or 'n'.")
def game_round():
"""Run one round of the guessing game."""
import random
secret = random.randint(1, 100)
attempts = 0
while True:
guess_input = input("Enter your guess (1‑100): ")
try:
guess = int(guess_input)
if not 1 <= guess <= 100:
print("Please enter a number between 1 and 100.")
continue
except ValueError:
print("Invalid input. Please enter an integer.")
continue
attempts += 1
if guess < secret:
print("Too low!")
elif guess > secret:
print("Too high!")
else:
print(f"Congratulations! You guessed it in {attempts} attempts.")
break
def main():
"""Control the flow of the whole program."""
while True:
game_round()               # play one game
if not play_again():       # ask to play again
print("Thanks for playing!")
break                  # stop the program
if __name__ == "__main__":
main()
```
The program now repeats the guessing game as many times as the player chooses, handling all input validation and providing clear prompts.
